// NormalizeNFD applies Unicode canonical decomposition with canonical
// ordering (equivalent to String.prototype.normalize("NFD")); the mapping
// table holds full recursive decompositions, so one pass plus a stable
// combining-class sort completes the algorithm.
func NormalizeNFD(s string) string {
	var decomposed []rune
	for _, r := range s {
		if seq, ok := nfdDecompositions[r]; ok {
			decomposed = append(decomposed, seq...)
		} else {
			decomposed = append(decomposed, r)
		}
	}

	// Canonical ordering: stable insertion sort by combining class; the key
	// is fixed at the starting index and only shifts past strictly-greater
	// predecessors.
	for i := 1; i < len(decomposed); i++ {
		c := combiningClass(decomposed[i])
		if c == 0 {
			continue
		}
		for j := i; j > 0; j-- {
			prev := combiningClass(decomposed[j-1])
			if prev == 0 || prev <= c {
				break
			}
			decomposed[j-1], decomposed[j] = decomposed[j], decomposed[j-1]
		}
	}
	return string(decomposed)
}
